/*
 * Load a point from its uncompressed encoding without going through
 * mbedtls_ecp_point_read_binary().
 *
 * That function also accepts the compressed forms 02 and 03, and recovering
 * the missing coordinate means taking a modular square root - which reaches
 * mbedtls_mpi_exp_mod(), whose Montgomery multiplication depends on
 * mbedtls_ct_memcpy_if(). That symbol is not in the firmware's mbed TLS
 * archive and is not exported by the firmware either, so merely linking the
 * decompression path makes the application unloadable. See docs/platform.md.
 *
 * ICAO 9303-11 mandates the uncompressed encoding of TR-03111, so nothing is
 * lost: the coordinates are assigned straight from their big endian bytes.
 *
 * They used to be formatted as hexadecimal and handed to
 * mbedtls_ecp_point_read_string(), because a point's coordinates are declared
 * MBEDTLS_PRIVATE. That cost 490 bytes of code - mbedtls_mpi_read_string() and
 * its digit parser, linked for nothing else - and put two 133 byte buffers on
 * the stack of a function called during PACE. MBEDTLS_ALLOW_PRIVATE_ACCESS at
 * the top of this file removes both. It is exactly what
 * mbedtls_ecp_point_read_string() does internally: read X, read Y, set Z to 1.
 */
static int emrtd_ec_point_load_xy(
    mbedtls_ecp_point* point,
    const uint8_t* x,
    const uint8_t* y,
    size_t size) {
    if(size > EMRTD_EC_COORD_MAX) {
        return MBEDTLS_ERR_ECP_BAD_INPUT_DATA;
    }

    int ret;
    if((ret = mbedtls_mpi_read_binary(&point->X, x, size)) != 0) {
        return ret;
    }
    if((ret = mbedtls_mpi_read_binary(&point->Y, y, size)) != 0) {
        return ret;
    }
    return mbedtls_mpi_lset(&point->Z, 1);
}

size_t emrtd_ec_curve_count(void) {
    return sizeof(emrtd_curves) / sizeof(emrtd_curves[0]);
}

const EmrtdCurve* emrtd_ec_curve_at(size_t index) {
    return index < emrtd_ec_curve_count() ? &emrtd_curves[index] : NULL;
}

const EmrtdCurve* emrtd_ec_curve_by_param_id(uint8_t param_id) {
    for(size_t i = 0; i < emrtd_ec_curve_count(); i++) {
        if(emrtd_curves[i].param_id == param_id) {
            return &emrtd_curves[i];
        }
    }
    return NULL;
}

bool emrtd_ec_curve_supported(const EmrtdCurve* curve) {
    /*
     * Both halves, and not because one implies the other today. The table
     * carries parameters only for the curves this build can compute, so the
     * bit length and the presence of the bytes are two statements of the same
     * fact - and the day one of them is edited without the other, this asks
     * the question that cannot be got wrong.
     */
    return curve != NULL && curve->p != NULL && curve->bits <= MBEDTLS_ECP_MAX_BITS;
}

int emrtd_ec_group_load(mbedtls_ecp_group* grp, const EmrtdCurve* curve) {
    if(grp == NULL || !emrtd_ec_curve_supported(curve)) {
        return MBEDTLS_ERR_ECP_BAD_INPUT_DATA;
    }

    int ret;
    mbedtls_ecp_group_init(grp);

    /*
     * MBEDTLS_ECP_DP_NONE keeps mbed TLS from assuming one of its built in
     * curves; grp->modp stays NULL, which selects the generic modular
     * reduction. The cofactor is deliberately left at the zero set by
     * mbedtls_ecp_group_init(): mbedtls_ecp_group_free() only releases the
     * parameter MPIs when it is not one, and ours are heap allocated. The
     * field takes no part in the arithmetic (ecp.c reads it only there).
     */
    grp->id = MBEDTLS_ECP_DP_NONE;

    if((ret = mbedtls_mpi_read_binary(&grp->P, curve->p, curve->size)) != 0) goto fail;
    if((ret = mbedtls_mpi_read_binary(&grp->A, curve->a, curve->size)) != 0) goto fail;
    if((ret = mbedtls_mpi_read_binary(&grp->B, curve->b, curve->size)) != 0) goto fail;
    if((ret = mbedtls_mpi_read_binary(&grp->N, curve->n, curve->size)) != 0) goto fail;

    grp->pbits = mbedtls_mpi_bitlen(&grp->P);
    grp->nbits = mbedtls_mpi_bitlen(&grp->N);

    /*
     * The coordinates of an mbedtls_ecp_point are private in mbed TLS 3, so
     * the generator is assigned through the one public call that takes them
     * directly. See emrtd_ec_point_load_xy() for why the binary reader is
     * avoided throughout this file.
     */
    if((ret = emrtd_ec_point_load_xy(&grp->G, curve->gx, curve->gy, curve->size)) != 0) {
        goto fail;
    }

    return 0;

fail:
    mbedtls_ecp_group_free(grp);
    return ret;
}

int emrtd_ec_point_read(
    mbedtls_ecp_group* grp,
    mbedtls_ecp_point* point,
    const uint8_t* data,
    size_t len) {
    if(len < 1 || data[0] != 0x04) {
        /* ICAO 9303-11 mandates the uncompressed encoding of TR-03111. */
        return MBEDTLS_ERR_ECP_FEATURE_UNAVAILABLE;
    }
    const size_t size = (mbedtls_mpi_bitlen(&grp->P) + 7) / 8;
    if(len != 1 + 2 * size) {
        return MBEDTLS_ERR_ECP_BAD_INPUT_DATA;
    }

    int ret = emrtd_ec_point_load_xy(point, data + 1, data + 1 + size, size);
    if(ret != 0) {
        return ret;
    }
    /* A point off the curve would leak the private scalar, so refuse it. */
    return mbedtls_ecp_check_pubkey(grp, point);
}

int emrtd_ec_point_write(
    const mbedtls_ecp_group* grp,
    const mbedtls_ecp_point* point,
    uint8_t* out,
    size_t out_size,
    size_t* out_len) {
    return mbedtls_ecp_point_write_binary(
        grp, point, MBEDTLS_ECP_PF_UNCOMPRESSED, out_len, out, out_size);
}

int emrtd_ec_point_x(
    const mbedtls_ecp_group* grp,
    const mbedtls_ecp_point* point,
    size_t coord_size,
    uint8_t* out) {
    /*
     * Both coordinates of the shared point land here and only x is wanted, so
     * y would otherwise stay on the stack of the NFC thread for the rest of
     * the read. The allocator clears that stack only when the thread is freed
     * (docs/platform.md, item 23), and a running thread's stack keeps the
     * frames it has returned from.
     */
    uint8_t encoded[1 + 2 * EMRTD_EC_COORD_MAX];
    size_t olen = 0;
    int ret = emrtd_ec_point_write(grp, point, encoded, sizeof(encoded), &olen);
    if(ret == 0 && olen != 1 + 2 * coord_size) {
        ret = MBEDTLS_ERR_ECP_BAD_INPUT_DATA;
    }
    if(ret == 0) {
        memcpy(out, encoded + 1, coord_size);
    }
    emrtd_secure_wipe(encoded, sizeof(encoded));
    return ret;
}
